  "inlineSchema": "// Skema Prisma — maganghub-attendance-web\n// Sumber kebenaran: SPEC.md §7 (Model Data).\n// Tahap 1 hanya memasang model inti yang dibutuhkan auth + fondasi fitur.\n//\n// Catatan: model fitur (MaganghubCredential, ReportTemplate, Report,\n// SubmitLog, AutomationConfig) sudah ada di sini sejak awal supaya migrasi\n// cukup sekali dan tidak berubah-ubah (SPEC.md §7, §14 Tahap C).\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ---------------------------------------------------------------------------\n// Enum\n// ---------------------------------------------------------------------------\n\nenum Role {\n  USER\n  ADMIN\n}\n\nenum CredentialStatus {\n  UNVERIFIED\n  ACTIVE\n  INVALID\n}\n\nenum SourceType {\n  TEMPLATE\n  MANUAL_EDIT\n}\n\nenum ReportStatus {\n  DRAFT\n  SUBMITTED\n  FAILED\n  PRESENT_ALREADY_EXISTS\n}\n\nenum SubmitStatus {\n  SUCCESS\n  FAILED\n  DUPLICATE\n}\n\nenum TriggerType {\n  MANUAL\n  CRON\n}\n\n// ---------------------------------------------------------------------------\n// Model Auth — NextAuth v5 (SPEC.md §7, §9)\n// ---------------------------------------------------------------------------\n\nmodel User {\n  id            String    @id @default(cuid())\n  email         String    @unique\n  passwordHash  String\n  name          String?\n  role          Role      @default(USER)\n  emailVerified DateTime?\n  image         String?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  accounts   Account[]\n  sessions   Session[]\n  credential MaganghubCredential?\n  template   ReportTemplate?\n  reports    Report[]\n  submitLogs SubmitLog[]\n  automation AutomationConfig?\n\n  @@map(\"users\")\n}\n\nmodel Account {\n  id                String  @id @default(cuid())\n  userId            String\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String?\n  access_token      String?\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String?\n  session_state     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n  @@map(\"accounts\")\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String\n  expires    DateTime\n\n  @@unique([identifier, token])\n  @@map(\"verification_tokens\")\n}\n\n// ---------------------------------------------------------------------------\n// Model Fitur\n// ---------------------------------------------------------------------------\n/// Kredensial Monev pengguna. Password TIDAK pernah disimpan mentah —\n/// hanya ciphertext AES-256-GCM beserta IV dan auth tag (SPEC.md §9 poin 1).\nmodel MaganghubCredential {\n  id               String           @id @default(cuid())\n  userId           String           @unique\n  emailMonev       String\n  ciphertext       String\n  iv               String\n  authTag          String\n  // Token sesi Monev (`monev_refresh_token`, HttpOnly di browser). Disimpan\n  // terenkripsi AES-256-GCM sama seperti password, tapi di kolom terpisah\n  // supaya password asli tidak ikut terhapus saat tes koneksi memperbarui\n  // token. Opsi C1 (docs/MONEV-API.md §7) — pengguna menempel token sekali.\n  // Boleh NULL: pengguna boleh menyimpan password saja tanpa token.\n  tokenCiphertext  String?\n  tokenIv          String?\n  tokenAuthTag     String?\n  // Access token hasil login otomatis (Opsi A). Berumur pendek (6 jam), jadi\n  // disimpan terpisah dari refresh token (30 hari). Diisi oleh\n  // `POST /api/credentials/login`; kalau kosong, `access_token` akan\n  // diterbitkan ulang saat dibutuhkan. Terenkripsi AES-256-GCM sama seperti\n  // password. Boleh NULL: pengguna yang menempel refresh token manual tidak\n  // punya access token tersimpan sampai login otomatis dijalankan.\n  accessCiphertext String?\n  accessIv         String?\n  accessAuthTag    String?\n  accessExpiresAt  DateTime?\n  status           CredentialStatus @default(UNVERIFIED)\n  createdAt        DateTime         @default(now())\n  updatedAt        DateTime         @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"maganghub_credentials\")\n}\n\n/// Tiga template tetap: uraian aktivitas, pembelajaran, kendala.\n/// Isinya >100 karakter (syarat portal) dan dipakai ulang setiap hari —\n/// persis perilaku bot Python (SPEC.md §1, §5.3, §13 baris 9).\nmodel ReportTemplate {\n  id        String   @id @default(cuid())\n  userId    String   @unique\n  activity  String\n  learning  String\n  obstacles String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"report_templates\")\n}\n\n/// Satu laporan untuk satu tanggal. `source` menandai apakah isinya\n/// diambil apa adanya dari template atau diedit manual (SPEC.md §7).\nmodel Report {\n  id        String       @id @default(cuid())\n  userId    String\n  date      DateTime     @db.Date\n  activity  String\n  learning  String\n  obstacles String\n  source    SourceType   @default(TEMPLATE)\n  status    ReportStatus @default(DRAFT)\n  createdAt DateTime     @default(now())\n  updatedAt DateTime     @updatedAt\n\n  user       User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  submitLogs SubmitLog[]\n\n  @@unique([userId, date])\n  @@index([userId, date])\n  @@map(\"reports\")\n}\n\n/// Audit log tiap percobaan submit — bukti \"sudah dikirim\" bila disengketakan\n/// (SPEC.md §7, §10). Tidak boleh ada submit yang tidak tercatat di sini.\nmodel SubmitLog {\n  id        String       @id @default(cuid())\n  reportId  String?\n  userId    String\n  status    SubmitStatus\n  message   String?\n  httpCode  Int?\n  trigger   TriggerType\n  attempt   Int          @default(1)\n  createdAt DateTime     @default(now())\n\n  report Report? @relation(fields: [reportId], references: [id], onDelete: SetNull)\n  user   User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, createdAt])\n  @@map(\"submit_logs\")\n}\n\n/// Pengaturan pemicu otomatis per pengguna. `webhookKey` adalah rahasia\n/// milik pengguna sendiri — jangan satu kunci untuk semua (SPEC.md §9 poin 7).\nmodel AutomationConfig {\n  id         String   @id @default(cuid())\n  userId     String   @unique\n  isEnabled  Boolean  @default(false)\n  webhookKey String   @unique\n  hour       Int      @default(7)\n  minute     Int      @default(30)\n  timezone   String   @default(\"Asia/Jakarta\")\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"automation_configs\")\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"sessions\")\n}\n",
